#include <string.h>
#include <stdio.h>

typedef struct { const char *name; double arrival; double service; } Job;

/* jobs: 作业数组；n: 作业数；algo: "FCFS" / "SJF" / "HRRN"
 * out:  输出作业名顺序；返回作业数 n */
int solve(const Job *jobs, int n, const char *algo, const char **out) {
    int done[256] = {0};
    double t = 0.0;

    for (int step = 0; step < n; ++step) {
        /* 找当前已到达且未完成的作业中最优者 */
        int pick = -1;
        for (int i = 0; i < n; ++i) {
            if (done[i] || jobs[i].arrival > t) continue;
            if (pick == -1) { pick = i; continue; }

            int better = 0;
            if (!strcmp(algo, "FCFS")) {
                better = (jobs[i].arrival < jobs[pick].arrival);
            } else if (!strcmp(algo, "SJF")) {
                if (jobs[i].service != jobs[pick].service)
                    better = (jobs[i].service < jobs[pick].service);
                else
                    better = (jobs[i].arrival < jobs[pick].arrival);
            } else { /* HRRN */
                double ri = (t - jobs[i].arrival + jobs[i].service) / jobs[i].service;
                double rp = (t - jobs[pick].arrival + jobs[pick].service) / jobs[pick].service;
                if (ri != rp) better = (ri > rp);
                else better = (jobs[i].service < jobs[pick].service);
            }
            if (better) pick = i;
        }

        if (pick == -1) {
            /* 当前无就绪作业：时间推进到最早到达者 */
            double nxt = -1;
            for (int i = 0; i < n; ++i)
                if (!done[i] && (nxt < 0 || jobs[i].arrival < nxt)) nxt = jobs[i].arrival;
            t = nxt;
            step--; /* 重新为本轮选择 */
            continue;
        }

        done[pick] = 1;
        out[step] = jobs[pick].name;
        if (jobs[pick].arrival > t) t = jobs[pick].arrival;
        t += jobs[pick].service;
    }
    return n;
}
